import{_ as d,o as e,c as o,a3 as c}from"./chunks/framework.DAK02U1-.js";const p=JSON.parse('{"title":"配置参考","description":"","frontmatter":{"outline":2,"head":[["meta",{"property":"og:title","content":"配置参考 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/clice/guide/configuration"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/clice/guide/configuration"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/guide/configuration"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/guide/configuration"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/guide/configuration"}]]},"headers":[],"relativePath":"zh/clice/guide/configuration.md","filePath":"zh/clice/guide/configuration.md","lastUpdated":1794738697000}'),a={name:"zh/clice/guide/configuration.md"};function i(h,t,r,n,l,s){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="configuration-reference" tabindex="-1"><span id="配置参考" class="heading-alias"></span>配置参考 <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to &quot;配置参考&quot;">​</a></h1><p>本页列出所有选项；常见用法见<a href="./config-guide">配置指南</a>。</p><p>clice 从项目根目录的 <code>clice.toml</code> 读取配置；若该文件不存在，则从 <code>.clice/config.toml</code> 读取。配置也可以由 LSP 的 <code>initializationOptions</code>（JSON 格式）传入；<code>initializationOptions</code> 中的值覆盖配置文件，合并后仍未设置的项由默认值填充。</p><p>配置仅在服务器启动时读取一次，不支持热重载。当项目的配置文件被保存、创建或删除时，服务器会请求编辑器重启自身：VS Code（通过 socket 连接服务器时除外）以及 Neovim 0.12 及更高版本会自动重启它；其他编辑器会在该文件上显示一条诊断（文件被删除时则显示一条消息），说明修改将在 clice 重启后生效。</p><p>clice 无法采纳的配置会视为错误：无法解析的文件、类型错误的值、超出选项可选范围的值、为零的 worker 数量或上限、无法编译或含有反斜杠的模式、未设置的变量、没有任何规则标签声明的 <code>default_configuration</code>，以及 clice 1.0 之前旧版布局中的键（错误信息会指明它迁移到了何处）。服务器会将每个问题作为错误诊断显示在该文件上，并在修正后的文件保存之前暂停该项目的所有服务；命令行运行则会逐一指出每个问题及其位置，并以退出码 2 退出。clice 不认识的键只会在文件上产生一条警告，其余配置照常生效。来自 <code>initializationOptions</code> 的设置若有错误，会以消息形式提示，且在修正这些设置并重启 clice 之前不会为该项目提供任何服务。</p><p>完整配置的 JSON Schema 发布在 <a href="/clice-config.schema.json"><code>clice-config.schema.json</code></a>；支持按 Schema 校验 TOML 或 JSON 的编辑器均可指向该地址。VS Code 扩展已为 <a href="https://marketplace.visualstudio.com/items?itemName=tamasfe.even-better-toml" target="_blank" rel="noreferrer">Even Better TOML</a> 将其关联到这两个配置文件，提供补全与校验；在其他环境中，在文件首行写入 <code>#:schema https://docs.clice.io/clice-config.schema.json</code> 即可让 taplo（Zed 与 Neovim 配置中常用的 TOML 语言服务器）使用该 Schema。</p><p>相对路径和模式均相对于项目根目录解析，无论它们写在 <code>clice.toml</code>、<code>.clice/config.toml</code> 还是 <code>initializationOptions</code> 中。</p><p>配置项分为两类。作用于整个服务器的选项——缓存与日志目录、检查磁盘的频率、运行的 worker 数量——是顶层键，或位于 <code>[workers]</code> 中。可按文件分别设定的选项——后台索引是否编译该文件、是否解析并索引其函数体、如何为其提供服务、做 Lint 和格式化——是 <code>[[rules]]</code> 的字段：若要对所有文件生效，请将其写在最后一条不带 <code>patterns</code> 的规则上。各功能配置节（<code>[hover]</code>、<code>[inlay_hints]</code> 等）存放对应功能的偏好设置。</p><h2 id="several-folders" tabindex="-1"><span id="多个文件夹" class="heading-alias"></span>多个文件夹 <a class="header-anchor" href="#several-folders" aria-label="Permalink to &quot;多个文件夹&quot;">​</a></h2><p>编辑器打开的每个工作区文件夹，只要含有 <code>clice.toml</code> 或 <code>compile_commands.json</code>（位于该文件夹本身，或位于其不含自身 <code>clice.toml</code> 的直接子目录中——即自动发现会查找的位置），就是一个独立的项目，各自拥有独立的 <code>clice.toml</code>、编译数据库和缓存目录。两者都不含、且位于另一个已打开文件夹内部的文件夹，则归入外层文件夹的项目中。在一个文件夹内部，含有自身 <code>clice.toml</code> 或 <code>.clice/config.toml</code> 的目录自成一个独立项目：外层文件夹的项目不会加载其中的任何编译数据库，也不会把其中的文件当作默认源文件或临时成员；不过若外层文件夹自身的数据库列出了这些文件，仍会在外层项目中编译它们。仅含编译数据库的目录则会作为独立项目，服务外层项目未构建的文件。在所有工作区文件夹之外打开的文件，归属于其上方最近的含有 <code>clice.toml</code> 或 <code>compile_commands.json</code>（直接位于该目录或其 <code>build/</code> 子目录中）的目录；该目录随后会像已打开的文件夹一样获得服务，除非已有正在服务的项目加载了那份数据库；上方没有此类目录且不被任何项目编译的文件则单独提供服务，使用默认命令，不借用各文件夹项目中的任何内容。文件由编译数据库中列有它的项目负责编译；自身没有数据库条目的头文件会从源文件包含了它的项目中借用宿主，并优先选择所在文件夹包含该头文件的项目。工作区符号搜索横跨所有项目；代码导航——查找引用、跳转到定义与声明、调用层次结构与类型层次结构、查找实现——会延伸到在同一文件中声明了该符号的其他项目。编辑器中已打开的文件只由服务它的项目作答，因此所有查询看到的都是它尚未保存的修改。</p><p><code>initializationOptions</code> 作用于每个项目，而一个缓存目录只服务一个项目：位于项目之外的缓存目录会记录最先使用它的项目；其他项目——无论是在当前服务器中，还是在之后的 <code>clice index</code> 运行中——都会依次回退到自身 <code>clice.toml</code> 指定的缓存目录、其文件夹内的 <code>.clice</code>，若这些目录也均被占用则无缓存运行，并告知用户缓存最终落在了何处。因此，<code>initializationOptions</code> 中填写的绝对路径 <code>cache_dir</code> 只会分配给第一个文件夹。worker 数量取启动时各文件夹所请求的最大值。列出或切换构建配置作用于请求所指定文件所属的项目（在 VS Code 中即当前活动编辑器的文件），未指定时则作用于第一个文件夹。</p><h2 id="logs" tabindex="-1"><span id="日志" class="heading-alias"></span>日志 <a class="header-anchor" href="#logs" aria-label="Permalink to &quot;日志&quot;">​</a></h2><p><code>clice serve</code>、<code>clice index</code> 和 <code>clice lint</code> 的每次运行都会在 <code>logging_dir</code>（默认为项目中的 <code>.clice/logs</code>）下创建各自的会话目录，目录名由启动时间和进程 ID 组成：其中包含服务器的 <code>master.log</code>（或命令行工具的 <code>index.log</code>、<code>lint.log</code>），以及每个 worker 各一份日志文件。服务器在打开第一个项目时开始写日志——没有编译数据库的文件夹会等到其中的文件被打开或出现编译数据库时才算打开——之后打开的其他项目都会在各自的日志目录中创建指向该会话日志的链接。每次运行只保留最近的 20 个会话（链接也计入在内），清理其余旧会话，但绝不删除进程仍在运行的会话。单个日志文件超过 64 MiB 时会轮转为 <code>&lt;name&gt;.1.log</code>（覆盖已有同名文件），并在新文件开头注明。</p><p>无论日志级别如何设置，日志文件始终记录 <code>info</code> 及以上级别的内容；环境变量 <code>CLICE_LOG_LEVEL</code>（可选 <code>trace</code>、<code>debug</code>、<code>info</code>、<code>warn</code>、<code>error</code>、<code>fatal</code> 或 <code>off</code>）控制输出到 stderr 的级别。编辑器会展示服务器的 stderr 输出，默认从 <code>info</code> 起（Neovim 配置使用 <code>warn</code>）；命令行工具则以 <code>warning: …</code> 和 <code>error: …</code> 的格式打印警告和错误。设置 <code>CLICE_LSP_TRACE=1</code> 后，由编辑器启动的服务器还会把收到（<code>&lt;-</code>）和发出（<code>-&gt;</code>）的每条 LSP 消息连同时间戳写入会话目录下的 <code>trace.log</code>，超过 64 MiB 时同样按日志规则轮转。编辑器会将这些环境变量传给它启动的服务器（VS Code 中配置 <code>clice.serverEnv</code>）。单个项目中的路径记为相对于项目根目录的路径；同时服务多个项目的服务器记为相对于公共父目录的路径（以文件夹名开头）；worker 自身的日志则写出完整路径。报告问题时请附上整个会话目录：<code>master.log</code> 记录了服务器执行的操作及耗时，崩溃时的调用栈保存在崩溃进程对应的日志中；worker 崩溃时，<code>master.log</code> 也会摘录其调用栈及最后几行日志。</p><h2 id="variable-substitution" tabindex="-1"><span id="变量替换" class="heading-alias"></span>变量替换 <a class="header-anchor" href="#variable-substitution" aria-label="Permalink to &quot;变量替换&quot;">​</a></h2><p><code>cache_dir</code>、<code>logging_dir</code>，以及规则的 <code>patterns</code>、<code>compile_commands</code>、<code>default_command</code>、<code>append</code> 和 <code>remove</code> 支持以下变量：</p><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>${workspace}</code></td><td>项目的根目录</td></tr><tr><td><code>${env:NAME}</code></td><td>服务器的环境变量 <code>NAME</code>；引用未设置的变量会报错。编辑器会将自身环境传给服务器，VS Code 还会合并 <code>clice.serverEnv</code></td></tr></tbody></table><p>在匹配模式中，变量值按字面字符匹配，绝不当作 glob 语法解析；在写成单个字符串的 <code>default_command</code> 中，含空格的变量值仍保持为单个参数。</p><h2 id="top-level" tabindex="-1"><span id="顶层选项" class="heading-alias"></span>顶层选项 <a class="header-anchor" href="#top-level" aria-label="Permalink to &quot;顶层选项&quot;">​</a></h2><p>顶层选项，写在所有配置节之前。</p><p>clice 会在后台检查磁盘上的文件，以便感知编辑器之外发生的改动（如 <code>git checkout</code>、重新生成的 <code>compile_commands.json</code>，或 agent、代码生成器写入的文件），无需重启服务器即可同步更新。每个依赖项目文件的请求在处理前也会先检查相应文件；工具链安装的头文件则会每隔几分钟、在其所属环境更新时以及每次保存时检查。将 <code>poll_seconds</code> 设为 <code>0</code> 可关闭后台轮询。</p><p>索引存放在缓存目录中，因此该目录必须位于本地磁盘：在网络文件系统（NFS、SMB、WSL 下的 Windows 盘符）上，clice 仅将索引保存在内存中并给出提示；此时请将 <code>cache_dir</code> 指向本地目录。在 macOS 上，Time Machine 和 iCloud 会备份并同步项目内的缓存目录，将 <code>cache_dir</code> 设在 <code>~/Library/Caches</code> 下即可避开它们。</p><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>default_configuration</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td></tr></tbody></table><p>当 <code>--configuration</code> 和持久化的选择均未指定配置时回退使用的构建配置，取规则上声明的标签之一；填写没有任何规则声明的名称会报错。未设置时，使用第一个声明的标签。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>cache_dir</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td></tr></tbody></table><p>统一磁盘缓存（PCH、PCM 和索引）的目录，相对于项目根目录。留空默认为 <code>${workspace}/.clice</code>，该目录会自动生成 .gitignore 和 CACHEDIR.TAG 标记，将自身排除在版本控制和备份之外（<code>.clice/config.toml</code> 对 Git 保持可见；遵循 CACHEDIR.TAG 的备份工具会跳过整个目录）；显式配置的目录不会写入这些标记。该目录必须位于本地磁盘：在网络文件系统（NFS、SMB、WSL 下的 Windows 盘符）上不会保存索引。解析后的最终路径会在启动时打印。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>logging_dir</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td></tr></tbody></table><p>日志文件目录，相对于项目根目录；留空时取 <code>${cache_dir}/logs</code>。服务器、<code>clice index</code> 和 <code>clice lint</code> 的每次运行都会将日志写入各自的子目录，保留最近的 20 个会话。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>poll_seconds</code></td><td><code>uint32</code></td><td><code>30</code></td></tr></tbody></table><p>后台两次检查同一项目文件之间的最长间隔（秒）：每次检查若发现文件未变，间隔时间翻倍，直至达到此上限。设为 0 会禁用后台轮询（包括编译数据库的轮询）。</p></div><h2 id="workers" tabindex="-1"><code>[workers]</code> <a class="header-anchor" href="#workers" aria-label="Permalink to &quot;`[workers]`&quot;">​</a></h2><p>clice 在独立的 worker 进程中执行编译。前台 worker 负责让已打开的文件保持编译状态并响应针对它们的请求；其余 worker 承担一次性任务——后台索引、代码补全、签名帮助、格式化、预编译头文件和模块——并按需启动：始终保留一个常驻待命，后台索引有任务排队时会按可用上限启动 worker，空闲满 30 秒的 worker 则自动退出。同时保留编译状态的已打开文件数量取决于机器内存。因内存不足被系统终止的 worker 会自动重建；以 systemd unit 运行 clice 时需配置 <code>OOMPolicy=continue</code>，因为默认策略会在任一子进程被杀时停掉整个 unit（连同服务器本身）。</p><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>foreground</code></td><td><code>uint32</code></td><td><code>2</code></td></tr></tbody></table><p>前台 worker 数量：负责让已打开的文件保持编译状态并响应相关请求（悬停、语义 Token 等）；至少为 1。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>background</code></td><td><code>&quot;auto&quot;</code> 或 <code>uint32</code></td><td><code>&quot;auto&quot;</code></td></tr></tbody></table><p>后台索引同时运行的编译任务上限，不会超过 <code>max</code>：&quot;auto&quot; 表示机器物理核心数的一半（且至少为 2），也可填至少为 1 的整数。在多核机器上调高此值可加快首次索引速度。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>max</code></td><td><code>&quot;auto&quot;</code> 或 <code>uint32</code></td><td><code>&quot;auto&quot;</code></td></tr></tbody></table><p>同时运行的编译 worker 总数上限（后台索引、代码补全、签名帮助以及预编译头文件和模块合计）：&quot;auto&quot; 表示机器的物理核心数，也可填至少为 1 的整数。这些 worker 按需启动，空闲 30 秒后退出。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>background_delay_ms</code></td><td><code>uint32</code></td><td><code>3000</code></td></tr></tbody></table><p>最后一次编辑或请求之后、后台索引开始运行前的等待时间（毫秒）。</p></div><h2 id="diagnostics" tabindex="-1"><code>[diagnostics]</code> <a class="header-anchor" href="#diagnostics" aria-label="Permalink to &quot;`[diagnostics]`&quot;">​</a></h2><p><code>[diagnostics]</code> 节控制 clice 为已打开文件发布的诊断。</p><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>clang_tidy</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>对已打开的文件运行 clang-tidy 并提供快速修复，使用最近的 <code>.clang-tidy</code> 所配置的检查项（未找到配置文件时使用一小组默认检查）。除非将 <code>slow_clang_tidy_checks</code> 设为 <code>true</code>，否则会跳过对编辑器而言过慢的检查项；在编辑中的代码上不可靠的检查项则始终跳过；<code>clice lint</code> 不检查的文件不会运行任何检查。<code>NOLINT</code> 注释也仅在启用此项时才会同时抑制编译器警告。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>slow_clang_tidy_checks</code></td><td><code>bool</code></td><td>未设置</td></tr></tbody></table><p>对已打开的文件也运行 <code>.clang-tidy</code> 中启用但对编辑器而言过慢或尚未测定编辑器耗时的检查项（例如 <code>misc-const-correctness</code> 会使大文件的编译耗时翻倍）：文件的每次编译都需等待它们跑完。未设置时，clice 会跳过这些检查项并提示一次它们的名称；设为 <code>false</code> 则静默跳过。无论此项如何设置，<code>clice lint</code> 都会运行它们。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>suppress</code></td><td><code>array of string</code></td><td><code>[]</code></td></tr></tbody></table><p>按诊断代码屏蔽已打开文件中的特定诊断：可填编译器警告选项（<code>-Wunused-variable</code>）、clang 内部的其他诊断名称（<code>err_undeclared_var_use</code>）、clang-tidy 检查项名称，或 clice 自身的警告代码（<code>toolchain-query-failed</code>）。适用于处理 clang 误报的代码：文件的其余功能照常工作，且 <code>clice lint</code> 仍会报告这些诊断。</p></div><h2 id="documentation" tabindex="-1"><code>[documentation]</code> <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;`[documentation]`&quot;">​</a></h2><p><code>[documentation]</code> 节控制 clice 解析文档注释的方式。</p><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>format</code></td><td><code>string</code></td><td><code>&quot;doxygen&quot;</code></td></tr></tbody></table><p>凡展示文档注释之处（悬停、代码补全、签名帮助、<code>clice query</code>）解析注释的方式：&quot;doxygen&quot; 解析 Doxygen 命令（<code>@brief</code>、<code>@param</code>、<code>@return</code> 等）及 Doxygen 支持的 Markdown，同时兼容 GTK-Doc 和 kernel-doc 写法；&quot;plain&quot; 按原文显示注释。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>inherit</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>重写方法自身没有文档注释时，显示被重写方法的文档注释。</p></div><h2 id="hover" tabindex="-1"><code>[hover]</code> <a class="header-anchor" href="#hover" aria-label="Permalink to &quot;`[hover]`&quot;">​</a></h2><p><code>[hover]</code> 节控制悬停卡片的渲染内容。</p><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>show_aka</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>显示类型别名实际代表的类型，例如 <code>size_type</code> 对应 <code>unsigned long</code>。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>max_members</code></td><td><code>uint32</code></td><td><code>20</code></td></tr></tbody></table><p>悬停在类或枚举上时，其定义中最多列出的成员数量：类的数据成员与成员类型，或枚举的枚举项；成员函数不在此列。设为 <code>0</code> 则仅显示声明。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>layout</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>悬停在任意位置的类或字段上时，显示编译器为其计算的内存布局：大小、对齐、字段偏移量及填充字节。</p></div><h2 id="document-symbols" tabindex="-1"><code>[document_symbols]</code> <a class="header-anchor" href="#document-symbols" aria-label="Permalink to &quot;`[document_symbols]`&quot;">​</a></h2><p><code>[document_symbols]</code> 节控制文件大纲列出的内容。</p><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>macros</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>列出文件中编写的 <code>#define</code>；头文件保护（include guard）宏始终不列出。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>locals</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>在函数节点下列出其函数体内声明的变量、局部类型和 Lambda。</p></div><h2 id="inlay-hints" tabindex="-1"><code>[inlay_hints]</code> <a class="header-anchor" href="#inlay-hints" aria-label="Permalink to &quot;`[inlay_hints]`&quot;">​</a></h2><p><code>[inlay_hints]</code> 节控制服务器生成哪些内联提示及其最大长度。修改在服务器重启后生效。</p><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>总开关：设为 <code>false</code> 会禁用所有内联提示。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>parameters</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>调用处的形参名提示，例如 <code>draw(width: 800, height: 600)</code>。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>mutable_references</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>用 <code>&amp;</code> 标记按非 const 引用传递的实参，例如 <code>mutate(&amp;value: v)</code>。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>prefixed_names</code></td><td><code>bool</code></td><td><code>false</code></td></tr></tbody></table><p>当实参名与形参名去掉单字母前缀后一致时（如将 <code>param</code> 传给 <code>aParam</code>），是否仍显示形参名提示。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>single_letter_names</code></td><td><code>bool</code></td><td><code>false</code></td></tr></tbody></table><p>单参数函数的形参名为单个字母时，是否仍显示形参名提示，例如 <code>push_back(x: 1)</code>。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>deduced_types</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>为 <code>auto</code> 变量、结构化绑定（structured bindings）、初始化捕获（init-captures）、<code>auto</code> 形参、<code>decltype</code> 指代的类型以及推导返回类型显示推导类型提示。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>spelled_types</code></td><td><code>bool</code></td><td><code>false</code></td></tr></tbody></table><p>变量的初始化器中已写出目标类型时（如 <code>static_cast&lt;long&gt;(x)</code>、<code>Widget{1, 2}</code> 或 <code>std::make_unique&lt;Widget&gt;()</code>），是否仍显示推导类型提示。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>deduced_template_arguments</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>显示类模板实参推导（CTAD）得出的模板实参，例如 <code>std::pair pair(1, 2.5)</code> 中 <code>pair</code> 后的 <code>&lt;int, double&gt;</code>。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>designators</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>聚合初始化中的成员指派符提示，例如 <code>Point{1, 2}</code> 中的 <code>.x=</code> 和 <code>.y=</code>。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>array_indices</code></td><td><code>bool</code></td><td><code>false</code></td></tr></tbody></table><p>聚合初始化中的数组下标指派符提示，例如 <code>int pair[2] = {1, 2}</code> 中的 <code>[0]=</code> 和 <code>[1]=</code>。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>block_end</code></td><td><code>bool</code></td><td><code>false</code></td></tr></tbody></table><p>在函数、类型或控制流代码块的右花括号后显示 <code>// name</code>，点击可跳转到块开头。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>namespace_end</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>在命名空间的右花括号后显示 <code>// namespace name</code>，点击可跳转到命名空间开头。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>endif</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>在 <code>#endif</code> 后显示 <code>// condition</code>（即它所闭合的 <code>#if</code> 的条件），点击可跳转到对应的 <code>#if</code>。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>default_arguments</code></td><td><code>bool</code></td><td><code>false</code></td></tr></tbody></table><p>显示调用时省略的默认实参。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>min_block_lines</code></td><td><code>uint32</code></td><td><code>10</code></td></tr></tbody></table><p>代码块、命名空间或条件编译块在末尾显示提示所需的最小行数（首尾两行均计入）。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>max_length.types</code></td><td><code>&quot;unlimited&quot;</code> 或 <code>uint32</code></td><td><code>32</code></td></tr></tbody></table><p>推导类型或推导模板实参的最大字符数，或设为 <code>&quot;unlimited&quot;</code> 表示不限长度。放不下的模板实参会缩写为 <code>…</code>（如 <code>tuple&lt;int, string, …&gt;</code>）；若连最外层类型名都超出上限，则不显示该提示。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>max_length.default_arguments</code></td><td><code>&quot;unlimited&quot;</code> 或 <code>uint32</code></td><td><code>32</code></td></tr></tbody></table><p>所省略默认实参的最大字符数，或设为 <code>&quot;unlimited&quot;</code> 表示不限长度。过长的单个实参会缩写为 <code>…</code>，整个列表在超出上限处以 <code>…</code> 截断。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>max_length.block_end</code></td><td><code>&quot;unlimited&quot;</code> 或 <code>uint32</code></td><td><code>60</code></td></tr></tbody></table><p>块结尾或命名空间结尾标签的最大字符数，超出部分以 <code>…</code> 截断；也可设为 <code>&quot;unlimited&quot;</code> 表示不限长度。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>max_length.endif</code></td><td><code>&quot;unlimited&quot;</code> 或 <code>uint32</code></td><td><code>60</code></td></tr></tbody></table><p><code>#endif</code> 条件提示的最大字符数，超出部分以 <code>…</code> 截断；也可设为 <code>&quot;unlimited&quot;</code> 表示不限长度。</p></div><h2 id="semantic-tokens" tabindex="-1"><code>[semantic_tokens]</code> <a class="header-anchor" href="#semantic-tokens" aria-label="Permalink to &quot;`[semantic_tokens]`&quot;">​</a></h2><p><code>[semantic_tokens]</code> 节控制语义 Token 包含的内容，以及发送给客户端的种类（kind）与修饰符（modifier）名称。这些名称在编辑器连接时宣告，因此修改在服务器重启后生效。</p><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>lexical</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>同时发送编辑器自身语法高亮也会着色的 Token：关键字、字面量、注释、运算符、预处理指令。关闭时仅发送单靠语法无法区分的内容：按所指代实体分类的名称、重载运算符与声明符运算符、模板尖括号、格式化说明符，以及预处理非活动代码中的无种类 Token。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>kinds</code></td><td><code>table of string</code></td><td><code>{}</code></td></tr></tbody></table><p>将 clice 的 Token 种类映射为客户端或主题期望的名称，形如 <code>field = &quot;property&quot;</code>；映射为空字符串会丢弃该种类（不再发送其 Token），映射到同一名称的多个种类会合并。在服务器启动时读取。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>modifiers</code></td><td><code>table of string</code></td><td><code>{}</code></td></tr></tbody></table><p>将 clice 的 Token 修饰符映射为客户端或主题期望的名称；映射为空字符串会丢弃该修饰符，映射到同一名称的多个修饰符会合并。在服务器启动时读取。</p></div><h2 id="code-completion" tabindex="-1"><code>[code_completion]</code> <a class="header-anchor" href="#code-completion" aria-label="Permalink to &quot;`[code_completion]`&quot;">​</a></h2><p><code>[code_completion]</code> 节控制代码补全项的组装方式。</p><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>arguments</code></td><td><code>string</code></td><td><code>&quot;placeholders&quot;</code></td></tr></tbody></table><p>补全函数调用或模板时在名称后插入的内容：&quot;placeholders&quot; 插入圆括号或尖括号并为每个形参放置占位符；&quot;delimiters&quot; 插入空的圆括号或尖括号并将光标置于中间；&quot;none&quot; 仅插入名称本身。适用于函数、函数式宏、保存 Lambda 的变量，以及类模板、别名模板和变量模板；折叠为单个补全项的重载集只插入空括号。若实参已写出或该名称并非用于调用（如取函数地址），则不额外插入内容。不支持代码片段（snippet）的客户端只会获得函数调用的括号。Objective-C 消息会在选择器的每一段后插入占位符或空 Tab 停靠点；设为 &quot;none&quot; 或客户端不支持代码片段时仅插入第一段。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>bundle_overloads</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>将重载集折叠为单个补全项。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>statement_snippets</code></td><td><code>bool</code></td><td><code>false</code></td></tr></tbody></table><p>将 <code>if</code>、<code>for</code> 等语句补全为带各部分占位符的代码片段；关闭时仅插入关键字本身。客户端不支持代码片段时忽略此项。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>dot_to_arrow</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>在指针后输入 <code>.</code> 时，列出 <code>-&gt;</code> 可访问的成员，并在选中后自动将 <code>.</code> 改为 <code>-&gt;</code>。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>all_scopes</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>输入非限定名称时，同时提供项目中其他命名空间内与之匹配的名称，并自动补上所需的命名空间限定符；位于多个命名空间的同名符号按命名空间分别提供。当前文件已可见的名称直接提供；尚未引入的名称见 <code>insert_includes</code> 与 <code>insert_imports</code>。其他命名空间中的名称取自索引。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>insert_includes</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>配合 <code>all_scopes</code> 使用时，同时提供当前文件尚未包含的头文件中声明的名称与定义的宏，并在选中时自动插入对应头文件的 <code>#include</code>。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>insert_imports</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>配合 <code>all_scopes</code> 使用时，同时提供当前文件尚未导入的模块所导出的名称，并在选中时自动插入 <code>import</code>。若项目构建了 <code>std</code> 模块，已导入其他模块的文件或模块单元会用 <code>import std;</code> 引入标准库名称，而非包含对应的头文件。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>limit</code></td><td><code>&quot;unlimited&quot;</code> 或 <code>uint32</code></td><td><code>100</code></td></tr></tbody></table><p>返回补全项的最大数量（保留排序最靠前的项），或设为 <code>&quot;unlimited&quot;</code> 表示不限数量。被截断的列表会标记为未完成，编辑器会在继续输入时重新发起请求。</p></div><h2 id="signature-help" tabindex="-1"><code>[signature_help]</code> <a class="header-anchor" href="#signature-help" aria-label="Permalink to &quot;`[signature_help]`&quot;">​</a></h2><p><code>[signature_help]</code> 节控制签名帮助弹窗的显示内容。</p><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>documentation</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>显示被调用函数的文档注释。</p></div><h2 id="references" tabindex="-1"><code>[references]</code> <a class="header-anchor" href="#references" aria-label="Permalink to &quot;`[references]`&quot;">​</a></h2><p><code>[references]</code> 节控制查找引用的返回结果。</p><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>limit</code></td><td><code>&quot;unlimited&quot;</code> 或 <code>uint32</code></td><td><code>2000</code></td></tr></tbody></table><p>单次查找引用请求最多返回的位置数量，或设为 <code>&quot;unlimited&quot;</code> 表示不限数量。结果被截断时，优先保留发起请求所在文件中的位置。<code>clice query references</code> 始终列出全部结果。</p></div><h2 id="rules" tabindex="-1"><code>[[rules]]</code> <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;`[[rules]]`&quot;">​</a></h2><p>规则用模式匹配文件，规定这些文件从何处获取编译命令、如何增删命令参数，以及如何索引、服务、Lint 和格式化这些文件。匹配某个文件的所有规则按声明顺序依次应用：靠前规则的编译数据库在该文件的候选中优先级更高；<code>append</code> 与 <code>remove</code> 逐条累加，靠后的 <code>remove</code> 可抵消靠前的 <code>append</code>；其余所有字段（<code>default_command</code>、<code>background_index</code>、<code>readonly</code>、<code>lint</code> 等）均由第一条设置了该字段的匹配规则决定，若无规则设置则取默认值。因此，针对部分文件的规则应放在针对全部文件的规则之前：不带 <code>patterns</code> 的规则若未放在最后，且设置了后续规则也设置的字段，会产生一条警告，因为后续规则的该值永远不会生效。带有 <code>configuration</code> 标签的规则仅在该配置处于活动状态时生效；所有不重复的标签共同组成构建配置菜单。运行 <code>clice command &lt;file&gt;</code> 可查看指定文件在下方自 <code>query_toolchain</code> 起各个字段的最终生效值，以及决定该值的规则。</p><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>patterns</code></td><td><code>array of string</code></td><td><code>[]</code></td></tr></tbody></table><p>用于筛选本规则适用文件的 glob 模式。相对模式以项目根目录为起点（允许包含 <code>..</code> 路径段）；绝对模式或以 <code>**</code> 开头的模式匹配文件的绝对路径。<code>*</code> 匹配单个路径段内的任意字符，<code>?</code> 匹配单个字符，<code>**</code> 匹配任意层级的路径段，<code>{a,b}</code> 匹配备选项，<code>[0-9]</code> 匹配字符范围，<code>[!...]</code> 匹配取反的字符范围，<code>[*]</code> 匹配字面字符 <code>*</code>。所有平台上的路径分隔符均为 <code>/</code>。省略此项表示匹配所有文件：此类规则应放在最后，为上方规则未决定的选项兜底。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>configuration</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td></tr></tbody></table><p>构建配置标签。带标签的规则仅在该配置处于活动状态时生效；不带标签的规则始终生效。所有不同的标签共同组成配置菜单；<code>--configuration</code>、持久化保存的选择与 <code>default_configuration</code> 按此优先级顺序决定当前活动的配置。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>compile_commands</code></td><td><code>array of string</code></td><td><code>[]</code></td></tr></tbody></table><p>按优先级排列的编译数据库列表：可填 compile_commands.json 文件路径或包含它的目录路径（相对于项目根目录）。列出的数据库都会加载，且其中每条记录无论规则模式如何都作用于记录自身对应的文件；规则模式与顺序决定了同一文件出现在多个数据库中时默认选用哪条记录。不带模式的规则用于指定整个项目的数据库。当没有任何规则声明来源时，项目根目录及其直接子目录中的所有 compile_commands.json 都会自动加载，打开文件时其上层各级目录中的数据库也会加载；但根目录下含有自身 clice.toml 或 .clice/config.toml 的子目录属于独立项目，其中的数据库不会加载。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>resolve_symlinks</code></td><td><code>bool</code></td><td><code>false</code></td></tr></tbody></table><p>是否按本规则的 <code>compile_commands</code> 经符号链接和 Windows junction 解析后的真实路径（而非配置名）来区分不同构建：适用于用链接指向当前构建目录的构建系统。每个真实路径各自维护一份索引；当链接改指其他目录时，服务器会请求重启以切换到目标构建的索引，其中仍保留此前会话为该构建建立的数据。若另一配置的规则与当前配置的唯一区别是直接写明了同一批编译数据库路径，则两者共享同一份索引。不再使用的构建索引会保留在缓存目录中，直至手动删除。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>default_command</code></td><td><code>string</code> 或 <code>array of string</code></td><td><code>&quot;&quot;</code></td></tr></tbody></table><p>匹配本规则但没有编译数据库条目的文件所使用的编译命令（不含源文件路径本身）：可为按 shell 命令行规则分词的字符串，或 argv 字符串数组。命令以项目根目录为工作目录运行，磁盘上匹配的源文件会加入后台索引（除非 <code>background_index</code> 设为 <code>false</code>）——在启动时枚举一次，并在每次轮询时重新枚举，因此后续新建的文件打开时即可编译，并在一个轮询周期内加入索引。clang 无法按扩展名识别语言的文件（如 Arduino 的 <code>.ino</code>、无扩展名的工具源码），仅当命令显式指定了语言（如 <code>-x c++</code>）且匹配模式点明了其后缀（如 <code>*.ino</code>）或文件名本身时，才会视为源文件。省略此项表示不设默认命令。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>append</code></td><td><code>array of string</code></td><td><code>[]</code></td></tr></tbody></table><p>为匹配文件追加的编译选项，例如 <code>[&quot;-std=c++20&quot;, &quot;-DNDEBUG&quot;]</code>。所有匹配规则追加的选项按声明顺序依次生效。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>remove</code></td><td><code>array of string</code></td><td><code>[]</code></td></tr></tbody></table><p>为匹配文件移除的编译选项（例如 <code>[&quot;-Wall&quot;]</code>），在本规则自身的 <code>append</code> 之前执行。带值的选项只移除该特定值（如 <code>-DDEBUG</code>），列表中的下一个元素与命令行一样视为独立的参数值；将值写为 <code>*</code>（如 <code>-I*</code>、<code>[&quot;-include&quot;, &quot;*&quot;]</code>）或在列表末尾省略值（如 <code>[&quot;-include&quot;]</code>）会移除该选项的所有值；紧跟在选项名后的 <code>*</code> 则会移除同类选项中所有带这一前缀的项（例如 <code>-W*</code> 会同时移除 <code>-Wall</code> 和 <code>-Wextra</code>）。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>query_toolchain</code></td><td><code>bool</code></td><td>未设置</td></tr></tbody></table><p>clice 是否运行匹配文件编译命令中的编译器，向其查询目标平台、标准库与系统头文件路径、预定义宏及默认语言标准。设为 <code>false</code> 时不运行外部编译器，由 clice 内置的 clang 直接按字面读取编译命令，并采用 clang 针对该编译器名称的默认设置。未设置时等同于 <code>true</code>。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>background_index</code></td><td><code>bool</code></td><td>未设置</td></tr></tbody></table><p>后台索引是否将匹配文件作为独立的翻译单元编译。设为 <code>false</code> 会跳过它们，并清除旧索引中关于它们的记录：打开这些文件时仍会正常编译，其中的头文件也仍会随包含它的翻译单元一起被索引。模块单元或生成预编译头文件的单元仍会在构建相应模块或预编译头文件时顺带建立索引，以供读取它们的文件使用。若不带匹配模式的规则将此项设为 <code>false</code>，后台索引将不编译任何文件。未设置时等同于 <code>true</code>。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>skip_function_body</code></td><td><code>bool</code></td><td>未设置</td></tr></tbody></table><p>包含匹配文件的编译是否跳过其函数体。未设置时，编辑器对已打开文件的编译会跳过文件顶部所包含头文件中的函数体——这能让打开与重编速度提升数倍，而这些函数体内部的错误会在后台索引编译完已保存版本后显示——其余所有编译仍会完整读取它们。设为 <code>true</code> 时，除匹配文件自身的编译外，其余所有编译（包括后台索引）都会跳过其函数体（含模板函数体），且不对其建立索引——这最适合仅被调用的第三方库代码，能大幅加快索引速度，代价是业务代码触发的库模板内部错误将不再显示；不过转发实参的模板（如 <code>make_unique</code>）以及 <code>constexpr</code> 和 <code>auto</code> 函数的函数体仍会照常读取。设为 <code>false</code> 时，任何编译都不跳过函数体，其中的错误会立即显示。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>index_function_body</code></td><td><code>bool</code></td><td>未设置</td></tr></tbody></table><p>索引是否记录匹配文件函数体内部引用的符号及其模板实例化的解析结果，使查找引用和调用层次结构能覆盖函数体内部。未设置时，对系统头文件为 <code>false</code>（系统库自身的内部细节通常只有阅读库源码时才会查询），对其余所有文件为 <code>true</code>。在编辑器中打开的文件无论如何都会完整索引。修改此项仅对之后新索引的翻译单元生效。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>readonly</code></td><td><code>string</code></td><td>未设置</td></tr></tbody></table><p>匹配文件打开时的服务方式：&quot;off&quot; 会编译文件——构建由首个需要编译结果的请求触发，等待期间先由索引回答；&quot;on&quot; 不构建 Preamble 的 PCH——只读查询完全由索引直接响应（尚未索引的文件会排到索引队列最前），而代码补全和签名帮助仍在无 Preamble 的情况下按需编译；&quot;auto&quot; 初始按 &quot;on&quot; 模式打开文件，首次出现编辑意图（修改内容、代码补全、签名帮助、切换上下文）时自动切换为 &quot;off&quot;，若索引无法服务该文件也会回退到 &quot;off&quot;。未设置时等同于 &quot;off&quot;。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>self_contained</code></td><td><code>bool</code></td><td>未设置</td></tr></tbody></table><p>匹配的头文件能否独立编译。<code>true</code>：头文件独立编译，不使用包含方的上下文；<code>false</code>：始终在包含它的文件上下文中编译。未设置时，clice 会先尝试单独编译一次头文件来自动判定。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>other_contexts</code></td><td><code>bool</code></td><td>未设置</td></tr></tbody></table><p>已打开的匹配文件在内容与索引记录一致期间，是否在当前上下文跳过的代码区域展示其他上下文在该处编译出的信息（索引中保存的语义着色、大纲、折叠范围、文档链接和悬停）。设为 <code>false</code> 则仅展示当前上下文自身的内容。编辑器中针对单个文件所做的选择（Show other contexts 或 Hide other contexts）在服务器停止前优先于此设置。未设置时等同于 <code>true</code>。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>lint</code></td><td><code>bool</code></td><td>未设置</td></tr></tbody></table><p><code>clice lint</code> 是否检查匹配文件，以及编辑器是否对它们运行 clang-tidy。设为 <code>false</code> 会跳过它们：丢弃其检查结果，且以它们为主文件的翻译单元也不会解析（除非 <code>--index</code> 需要为该单元建立索引）。项目目录之外的文件从不检查。未设置时等同于 <code>true</code>。</p></div><div class="config-option"><table tabindex="0"><thead><tr><th>选项</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td><code>format</code></td><td><code>bool</code></td><td>未设置</td></tr></tbody></table><p><code>clice format</code> 是否格式化匹配文件。设为 <code>false</code> 会跳过它们。项目目录之外的文件从不格式化。未设置时等同于 <code>true</code>。</p></div>',110)])])}const u=d(a,[["render",i]]);export{p as __pageData,u as default};
